/** The activity lines, in order. */
export async function activity(page: Page): Promise<string[]> {
  await page.getByTestId('activity-show').click();
  await page.waitForTimeout(300);
  return (await page.getByTestId('activity-line').allTextContents()).map((t) => t.trim());
}

/** The duplicate-claim lines, in order. */
export async function dups(page: Page): Promise<string[]> {
  await page.getByTestId('dups-show').click();
  await page.waitForTimeout(300);
  return (await page.getByTestId('dup-line').allTextContents()).map((t) => t.trim());
}

/** The claim's timeline: its lines are exactly `expected`, in order, each matched by its start. */
export async function expectClaimTimeline(page: Page, claimId: string, expected: string[]): Promise<void> {
  const c = claimRow(page, claimId);
  await c.getByTestId('claim-timeline').click();
  const lines = c.getByTestId('claim-timeline-line');
  await expect.poll(() => lines.count(), { timeout: WAIT }).toBe(expected.length);
  const texts = (await lines.allTextContents()).map((t) => t.trim());
  texts.forEach((line, i) => {
    const e = expected[i];
    const ok = line === e || line.startsWith(e + ' ');
    expect(ok, `timeline line ${i + 1}\n  expected: ${e}\n  actual:   ${line}`).toBe(true);
  });
}

/** Compare two snapshot dates: the result lines in order. */
export async function snapshotCompare(page: Page, from: string, to: string): Promise<string[]> {
  await page.getByTestId('snapshot-from').fill(from);
  await page.getByTestId('snapshot-to').fill(to);
  await page.getByTestId('snapshot-compare').click();
  await page.waitForTimeout(300);
  return (await page.getByTestId('snapshot-line').allTextContents()).map((t) => t.trim());
}

/** Roll the year over: how many periods were made, or null when refused. */
export async function rollover(page: Page, year: string): Promise<number | null> {
  await page.getByTestId('rollover-year').fill(year);
import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("claim timeline", () => {
  test("claim timeline", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-03-01"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    await ui.expectClaimTimeline(pg_uma, c_ada_0, [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`
    ]);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.editClaim(pg_uma, c_ada_1, {"note": "n"})).toBe(true);
    await ui.expectClaimTimeline(pg_uma, c_ada_1, [
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`
    ]);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    expect(await ui.remind(pg_vic, c_ada_0)).toBe(false);
    await ui.refresh(pg_uma);
    expect(await ui.statement(pg_uma, p_ada)).toBe(true);
    await ui.expectClaimTimeline(pg_uma, c_ada_0, [
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-01 number=FY2026-1 due=1.00`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01 number=FY2026-1`
    ]);
    await ui.expectClaimTimeline(pg_uma, c_ada_2, [
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`
    ]);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("SETTLED");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=vic role=steward`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01 number=FY2026-1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=1.00 overdue-total=0.00`,
      `CLAIM_EDITED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-01`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-01 number=FY2026-1 due=1.00`,
      `STATEMENT sheet=${sheet} by=uma name=Ada due-total=1.00 claims=1`
    ]);
  });

